script:
frappe.ui.form.on('Retention Receivable', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1) {
            frm.add_custom_button(__('Update Grand Total จาก Invoice'), function() {
                update_retention_from_invoice(frm);
            }, __("Actions"));
        }
    }
});

function update_retention_from_invoice(frm) {
    frappe.db.get_value('Sales Invoice', frm.doc.reference_name, ['custom_retention_amount', 'currency'], (r) => {
        if (r && r.custom_retention_amount !== undefined) {
            let new_total = r.custom_retention_amount;
            let currency = r.currency || 'THB';

            frappe.confirm(`ยอดใน Invoice คือ ${format_currency(new_total, currency)} <br>ต้องการอัปเดตยอดเงินและตัวอักษรใช่หรือไม่?`, () => {
                
                // คำนวณตัวหนังสือภาษาไทย (หรือตาม Currency ของระบบ)
                let in_words = frappe.utils.money_in_words(new_total, currency);

                frappe.call({
                    method: 'frappe.client.set_value',
                    args: {
                        doctype: 'Retention Receivable',
                        name: frm.doc.name,
                        fieldname: {
                            'grand_total': new_total,
                            'total_amount': new_total, // อัปเดตฟิลด์ยอดเงินหลักด้วย (ถ้ามี)
                            'in_words': in_words
                        },
                        value: "" // เมื่อส่งเป็น Object ใน fieldname ตัว value ให้ส่งว่างไว้
                    },
                    callback: function(res) {
                        if (!res.exc) {
                            frappe.show_alert({
                                message: __('อัปเดตยอดเงินและตัวอักษรเรียบร้อยแล้ว'),
                                indicator: 'green'
                            });
                            frm.reload_doc();
                        }
                    }
                });
            });
        } else {
            frappe.msgprint(__('ไม่พบยอดเงินใน Invoice อ้างอิง'));
        }
    });
}

frappe.ui.form.on('Purchase Order', {
    refresh: function(frm) {
        frm.remove_custom_button(__('Add Remark with QR'));
        frm.add_custom_button(__('Add Remark with QR'), function() {
            
            // 1. ตรวจสอบและโหลด Library qrcode.js หากยังไม่มีในเครื่อง
            if (typeof QRCode === "undefined") {
                frappe.require("https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js", function() {
                    show_qr_dialog(frm);
                });
            } else {
                show_qr_dialog(frm);
            }
        });
    }
});

// แยกฟังก์ชันออกมาเพื่อให้เรียกใช้ได้หลังจากโหลด Library เสร็จ
function show_qr_dialog(frm) {
    let d = new frappe.ui.Dialog({
        title: 'สร้าง Remark พร้อม QR (Local)',
        fields: [
            { label: 'สถานที่จัดส่ง', fieldname: 'location', fieldtype: 'Small Text', reqd: 1 },
            { label: 'URL', fieldname: 'url_link', fieldtype: 'Data', reqd: 1 }
        ],
        primary_action_label: 'ตกลง',
        primary_action(values) {
            // สร้าง Element ชั่วคราวเพื่อเจน QR Code
            const container = document.createElement('div');
            
            new QRCode(container, {
                text: values.url_link,
                width: 150,
                height: 150
            });

            // รอจังหวะให้ Library วาดรูปเสร็จ (เสี้ยววินาที)
            setTimeout(() => {
                const img_tag = container.querySelector('img');
                if (!img_tag) return;
                
                const img_base64 = img_tag.src;
                let description_html = `
                    <div style="font-family: sans-serif;">
                        <b>สถานที่จัดส่ง:</b> ${values.location}<br><br>
                        <img src="${img_base64}" width="75" height="75" style="display: block;">
                    </div>`;

                let child = frm.add_child('items');
                frappe.model.set_value(child.doctype, child.name, 'item_code', 'Remark');

                setTimeout(() => {
                    frappe.model.set_value(child.doctype, child.name, {
                        'description': description_html,
                        'qty': 1,
                        'uom': 'รายการ'
                    });
                    frm.refresh_field('items');
                }, 500);
            }, 200);

            d.hide();
        }
    });
    d.show();
}

frappe.ui.form.on('Transmittal Item', {
    // 1. ทำงานทันทีที่มีแถวใหม่เพิ่มเข้ามาในตาราง
    transmittal_item_add: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);

        // ใช้ setTimeout หน่วงเวลาเล็กน้อยเพื่อให้ระบบจับค่า reference ทัน
        setTimeout(() => { 
            if (row.reference) {
                fetch_check_fields(frm, row);
            }
        }, 150); 
    },

    // 2. ทำงานเมื่อมีการเลือกหรือเปลี่ยนค่าในฟิลด์ reference
    reference: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        if (row.reference) {
            fetch_check_fields(frm, row);
        }
    }
});

// ฟังก์ชันสำหรับวิ่งไปดึงข้อมูลจากเอกสารต้นทาง (Transmittal Entry)
function fetch_check_fields(frm, row) {
    frappe.call({
        method: 'frappe.client.get_value',
        args: {
            doctype: 'Transmittal Entry',
            filters: { name: row.reference },
            // ดึงฟิลด์ที่มี custom_ ตามที่คุณแจ้ง
            fieldname: ['custom_receipt_check', 'custom_tax_check', 'custom_wht_check', 'custom_retention_check']
        },
        callback: function(r) {
            if (r.message) {
                // แก้ไขจุดนี้: ดึงข้อมูลจาก r.message ด้วยชื่อฟิลด์ custom_ แล้วเอามาใส่ในฟิลด์ปลายทาง
                frappe.model.set_value(row.doctype, row.name, 'receipt_check', r.message.custom_receipt_check);
                frappe.model.set_value(row.doctype, row.name, 'tax_check', r.message.custom_tax_check);
                frappe.model.set_value(row.doctype, row.name, 'wht_check', r.message.custom_wht_check);
                frappe.model.set_value(row.doctype, row.name, 'retention_check', r.message.custom_retention_check);
            }
        }
    });
}

frappe.ui.form.on('Material Request', {
    // ---------------------------------------------------------
    // 3. ส่วนของการคำนวณตัวเลขและข้อความ
    // ---------------------------------------------------------
    validate: function(frm) {
        calculate_all_totals(frm);
    },

    custom_vat_override: function(frm) {
        calculate_all_totals(frm);
    },

    custom_paid_amount: function(frm) {
        update_thai_baht_text(frm);
    },

    custom_vat: function(frm) {
        if (frm.doc.custom_vat_override == 1) {
            calculate_all_totals(frm);
        }
    }
});

// ---------------------------------------------------------
// 4. ส่วนของ Child Table (Material Request Item)
// ---------------------------------------------------------
frappe.ui.form.on('Material Request Item', {
    qty: function(frm, cdt, cdn) {
        calculate_item_amount(frm, cdt, cdn);
    },
    rate: function(frm, cdt, cdn) {
        calculate_item_amount(frm, cdt, cdn);
    },
    custom_vat_nocal: function(frm, cdt, cdn) {
        calculate_all_totals(frm);
    },
    items_remove: function(frm) {
        calculate_all_totals(frm);
    }
});

function calculate_item_amount(frm, cdt, cdn) {
    let item = locals[cdt][cdn];
    let amount = flt(item.qty) * flt(item.rate);
    frappe.model.set_value(cdt, cdn, 'amount', amount);

    calculate_all_totals(frm);
}

function calculate_all_totals(frm) {
    let grand_total = 0;
    (frm.doc.items || []).forEach(function(item) {
        grand_total += flt(item.amount) || (flt(item.qty) * flt(item.rate));
    });
    frm.set_value('custom_grand_total', grand_total);

    let total_vat = 0;
    if (frm.doc.custom_vat_override == 1) {
        total_vat = flt(frm.doc.custom_vat);
    } else {
        (frm.doc.items || []).forEach(function(row) {
            if (row.custom_vat_nocal == 0 || !row.custom_vat_nocal) {
                let amount = flt(row.amount) || (flt(row.qty) * flt(row.rate));
                total_vat += (amount * 0.07);
            }
        });
        frm.set_value('custom_vat', total_vat);
    }

    let paid_amount = grand_total + total_vat;
    frm.set_value('custom_paid_amount', paid_amount);

    update_thai_baht_text(frm);
}

function update_thai_baht_text(frm) {
    let paid_amount = flt(frm.doc.custom_paid_amount);

    if (paid_amount > 0) {
        let thai_words = thai_baht_text(paid_amount);
        frm.set_value('custom_in_words', thai_words);
    } else {
        frm.set_value('custom_in_words', 'ศูนย์บาทถ้วน');
    }
}

function thai_baht_text(number) {
    number = parseFloat(number).toFixed(2);
    let numberArray = number.split('.');
    let baht = numberArray[0];
    let satang = numberArray[1];

    let bahtText = convert_to_thai_text(baht);
    let satangText = convert_to_thai_text(satang);

    let result = '';

    if (bahtText) {
        result += bahtText + 'บาท';
    }

    if (satangText && satang !== '00') {
        result += satangText + 'สตางค์';
    } else {
        result += 'ถ้วน';
    }

    return result;
}

function convert_to_thai_text(numberStr) {
    let thaiNumbers = ['ศูนย์', 'หนึ่ง', 'สอง', 'สาม', 'สี่', 'ห้า', 'หก', 'เจ็ด', 'แปด', 'เก้า'];
    let thaiPositions = ['', 'สิบ', 'ร้อย', 'พัน', 'หมื่น', 'แสน', 'ล้าน'];

    let text = '';
    let length = numberStr.length;

    if (length > 1) {
        numberStr = parseInt(numberStr, 10).toString();
        length = numberStr.length;
    }

    if (numberStr === '0') return '';

    for (let i = 0; i < length; i++) {
        let digit = parseInt(numberStr.charAt(i), 10);
        let position = length - i - 1;

        if (digit !== 0) {
            if (position === 0 && digit === 1 && length > 1) {
                text += 'เอ็ด';
            } 
            else if (position === 1 && digit === 2) {
                text += 'ยี่สิบ';
            } 
            else if (position === 1 && digit === 1) {
                text += 'สิบ';
            } 
            else {
                text += thaiNumbers[digit] + thaiPositions[position];
            }
        }
    }
    return text;
}

frappe.ui.form.on('Material Request', {
    validate: function(frm) {

        // หยุดทำงานเมื่อ custom_vat_override = 1
        if (frm.doc.custom_vat_override == 1) {
            return;
        }

        let total_vat = 0;

        // วนลูปอ่านค่าจาก Child Table ที่ชื่อว่า 'items'
        if (frm.doc.items && frm.doc.items.length > 0) {
            frm.doc.items.forEach(function(row) {

                // เปลี่ยนมาเช็คจากฟิลด์ custom_vat_nocal แทน
                if (row.custom_vat_nocal == 0 || !row.custom_vat_nocal) {

                    // ดึงค่า amount ของรายการนั้น
                    let amount = row.amount || 0;

                    // นำ amount มา * 7% แล้วบวกสะสม
                    total_vat += (amount * 0.07);
                }
            });
        }

        // เซ็ตค่าผลรวมทั้งหมดลงในฟิลด์ custom_vat ใน Parent Doctype
        frm.set_value('custom_vat', total_vat);
    }
});

frappe.ui.form.on('Material Request', {
    refresh: function(frm) {

        // ตรวจสอบว่า User ปัจจุบันมี Role ตามที่กำหนดหรือไม่
        let has_approval_role = frappe.user.has_role('Purchase Manager') || 
                                frappe.user.has_role('Purchase Master Manager') || 
                                frappe.user.has_role('System Manager');

        // แสดงปุ่มเฉพาะเอกสารที่เป็น Submit (docstatus === 1), ยังไม่อนุมัติ และมี Role ที่ถูกต้อง
        if (frm.doc.docstatus === 1 && frm.doc.custom_approve !== 'Approved' && has_approval_role) {

            // ปุ่ม Approve
            frm.add_custom_button(__('Approve'), function() {
                show_approve_dialog(frm);
            }, __('Approval'));

            // ปุ่ม Reject
            frm.add_custom_button(__('Reject'), function() {
                frappe.prompt([
                    {
                        label: 'เหตุผลที่ไม่อนุมัติ (Reject Reason)',
                        fieldname: 'reject_reason',
                        fieldtype: 'Small Text',
                        reqd: 1
                    }
                ], function(values) {

                    frm.set_value('custom_approve', 'Rejected');
                    frm.set_value('custom_approve_by', frappe.session.user);

                    let current_remark = frm.doc.custom_remark || ''; 
                    let new_text = 'เหตุผลที่ Reject: ' + values.reject_reason;
                    frm.set_value('custom_remark', current_remark ? (current_remark + '\n' + new_text) : new_text);

                    // สั่ง Update เอกสารหลังเซ็ตค่า
                    frm.save('Update').then(() => {
                        frappe.show_alert({message: 'ปรับสถานะเป็น Rejected พร้อมบันทึกเหตุผลเรียบร้อยแล้ว', indicator: 'red'});
                    });

                }, 'ระบุเหตุผลการไม่อนุมัติ', 'ตกลง (Reject)');

            }, __('Approval'));

            frm.page.set_inner_btn_group_as_primary(__('Approval'));
        }
    },

    // ดักการกด Cancel เอกสาร
    before_cancel: function(frm) {
        // 1. เคลียร์ค่าบนหน้าจอ (UI) โดยให้ลายเซ็นมีค่าเป็น null
        frm.set_value('custom_approve', '');
        frm.set_value('custom_approve_by', '');
        frm.set_value('custom_approve_signature', null); 

        // 2. บังคับอัปเดตฐานข้อมูลโดยตรงก่อนที่ระบบจะ Cancel (เคลียร์ Base64 ออกจาก DB)
        frappe.db.set_value(frm.doctype, frm.docname, {
            'custom_approve': '',
            'custom_approve_by': '',
            'custom_approve_signature': null 
        });

        frappe.show_alert('ระบบได้ล้างค่าการอนุมัติและลายเซ็นออกแล้ว', 5);
    },

    // เมื่อมีการกดปุ่มดึงลายเซ็นผู้ขอ
    custom_sign_request: function(frm) {
        frappe.db.get_value('User', frappe.session.user, 'bio')
            .then(r => {
                if (r.message && r.message.bio) {
                    let clean_base64 = r.message.bio.replace(/<[^>]*>?/gm, '').trim();

                    if (clean_base64.startsWith('data:image')) {
                        frm.set_value('custom_request_signature', clean_base64);
                        frappe.show_alert({message: 'ดึงลายเซ็นผู้ขอสำเร็จ', indicator: 'green'});
                    } else {
                        frappe.msgprint({
                            title: 'รูปแบบข้อมูลไม่ถูกต้อง',
                            message: 'ข้อมูลในช่อง Bio ไม่ใช่ Base64 ที่ถูกต้อง<br>ต้องขึ้นต้นด้วย <b>data:image...</b>',
                            indicator: 'red'
                        });
                    }
                } else {
                    frappe.msgprint({
                        title: 'ไม่พบลายเซ็น',
                        message: 'ไม่พบข้อมูลลายเซ็นในช่อง Bio ของผู้ใช้งานปัจจุบัน',
                        indicator: 'orange'
                    });
                }
            });
    }
});

// ฟังก์ชัน Dialog การ Approve
function show_approve_dialog(frm) {
    let d = new frappe.ui.Dialog({
        title: 'เซ็นชื่อเพื่ออนุมัติ (Approve)',
        fields: [
            {
                label: 'ลายเซ็น (Signature)',
                fieldname: 'signature',
                fieldtype: 'Signature',
                reqd: 1 
            },
            {
                fieldname: 'signature_preview',
                fieldtype: 'HTML'
            },
            {
                fieldname: 'fetch_from_user_btn',
                fieldtype: 'Button',
                label: 'ดึงลายเซ็นจากโปรไฟล์ (User Bio)',
                click: function() {
                    frappe.db.get_value('User', frappe.session.user, 'bio')
                        .then(r => {
                            if (r.message && r.message.bio) {
                                let clean_base64 = r.message.bio.replace(/<[^>]*>?/gm, '').trim();

                                if (clean_base64.startsWith('data:image')) {

                                    d.set_value('signature', clean_base64);

                                    let preview_html = `
                                        <div style="text-align: center; margin-top: 10px;">
                                            <span style="display: block; margin-bottom: 5px; color: #15803d; font-weight: bold;">
                                                ✓ ใช้ลายเซ็นจากโปรไฟล์แล้ว
                                            </span>
                                            <img src="${clean_base64}" style="max-height: 120px; border: 1px solid #d1d8dd; border-radius: 4px; padding: 5px; background: #fff;">
                                        </div>
                                    `;
                                    d.fields_dict.signature_preview.$wrapper.html(preview_html);
                                    d.fields_dict.signature.$wrapper.hide();

                                    frappe.show_alert({message: 'ดึงและแสดงรูปลายเซ็นสำเร็จ', indicator: 'green'});
                                } else {
                                    frappe.msgprint({
                                        title: 'รูปแบบข้อมูลไม่ถูกต้อง',
                                        message: 'ข้อมูลในช่อง Bio ไม่ใช่ Base64 ที่ถูกต้อง<br>ต้องขึ้นต้นด้วย <b>data:image...</b>',
                                        indicator: 'red'
                                    });
                                }
                            } else {
                                frappe.msgprint({
                                    title: 'ไม่พบลายเซ็น',
                                    message: 'ไม่พบข้อมูลในช่อง Bio ของผู้ใช้งานปัจจุบัน',
                                    indicator: 'orange'
                                });
                            }
                        });
                }
            }
        ],
        size: 'small',
        primary_action_label: 'ตกลง (Approve)',
        primary_action(values) {
            if (!values.signature) {
                frappe.msgprint('กรุณาเซ็นชื่อ หรือกดปุ่มดึงลายเซ็นจากโปรไฟล์');
                return;
            }

            frm.set_value('custom_approve_signature', values.signature);
            frm.set_value('custom_approve', 'Approved');
            frm.set_value('custom_approve_by', frappe.session.user);

            // สั่ง Update เอกสารหลังเซ็ตค่า (ใช้ 'Update' สำหรับเอกสารที่ Submit แล้ว)
            frm.save('Update').then(() => {
                frappe.show_alert({message: 'Approve เรียบร้อยแล้ว', indicator: 'green'});
                d.hide();
            }).catch(() => {
                d.hide();
            });
        }
    });

    d.show();
}
